    final result = await _remoteDataSource.login(
      email: email,
      password: password,
    );
    return _persistOnSuccess(result);
  }

  Future<Either<Failure, Session>> _persistOnSuccess(
    Either<Failure, Session> result,
  ) async {
    final session = result.toNullable();
